/// Keyword data for a language code, e.g. `"en"` or `"fr"`.
pub(crate) fn lang_keywords(lang: &str) -> Option<&'static LangKeywords> {
    LANG_KEYWORDS
        .iter()
        .find(|(code, _)| *code == lang)
        .map(|(_, kw)| kw)
}
